    "home_variable_rate_desc": "De la flexibilité si les taux baissent",
    "home_ratetypes_footer": "Vous ne savez pas lequel convient à vos projets? Consultez la comparaison complète <a href=\"full-service-mortgage-solution/#fixed-variable\" style=\"color:var(--rdc-gold);font-weight:800;\">taux fixe et taux variable</a> sur notre page Hypothèques.",
    "home_faq_kicker": "Questions fréquentes",
    "home_faq_title": "FAQ sur les hypothèques et le financement",
    "home_faq_desc": "Réponses rapides aux questions les plus fréquentes des acheteurs de maison et des propriétaires d'entreprise.",
    "home_faq1_q": "Combien puis-je me permettre d'emprunter?",
    "home_faq1_a": "Les prêteurs examinent généralement deux ratios : votre ratio d'amortissement brut de la dette (ABD), les frais de logement en pourcentage du revenu, habituellement plafonné autour de 39 %, et votre ratio d'amortissement total de la dette (ATD), tous les paiements de dettes en pourcentage du revenu, habituellement plafonné autour de 44 %. Votre limite exacte dépend de votre revenu, de vos dettes, de votre crédit et du taux du test de résistance hypothécaire.",
    "home_faq2_q": "Quelle est la différence entre la préqualification et la préapprobation?",
    "home_faq2_a": "La préqualification est une estimation rapide et informelle basée sur les chiffres que vous fournissez. La préapprobation est un examen plus approfondi où un prêteur vérifie votre revenu, votre crédit et vos dettes, et maintient généralement un taux pendant 60 à 120 jours, vous donnant un montant plus fiable pour magasiner.",
    "home_faq3_q": "De quelle mise de fonds ai-je besoin?",
    "home_faq3_a": "Au Canada, le minimum est de 5 % sur la première tranche de 500 000 $ du prix d'achat et de 10 % sur la portion entre 500 000 $ et 999 999 $. Les maisons à 1 000 000 $ ou plus nécessitent une mise de fonds d'au moins 20 %. Toute mise de fonds inférieure à 20 % nécessite une assurance prêt hypothécaire.",
    "home_faq4_q": "Qu'est-ce que le test de résistance hypothécaire?",
    "home_faq4_a": "Les prêteurs sous réglementation fédérale doivent vous qualifier au taux le plus élevé entre votre taux contractuel plus 2 % ou le taux de qualification de référence de la Banque du Canada, même si votre taux réel est inférieur. Cela vise à confirmer que vous pourriez toujours assumer les paiements si les taux augmentaient.",
    "home_faq5_q": "De quelle cote de crédit ai-je besoin pour être admissible?",
    "home_faq5_a": "La plupart des prêteurs traditionnels recherchent une cote de 680 ou plus pour les meilleurs taux. En dessous de ce seuil, vous pourriez tout de même être admissible auprès de prêteurs alternatifs ou privés, souvent avec une mise de fonds plus importante ou un taux légèrement plus élevé, ce à quoi nous pouvons vous aider à accéder.",
    "home_faq6_q": "Quelle est la différence entre un courtier hypothécaire et une banque?",
    "home_faq6_a": "Une banque ne peut vous offrir que ses propres produits hypothécaires. En tant que courtier hypothécaire agréé, Royal Den Capital compare les taux et les conditions des principales banques, caisses populaires, prêteurs alternatifs et privés en votre nom, sans coût direct pour vous dans la plupart des cas, puisque nous sommes rémunérés par le prêteur.",
    "home_faq7_q": "Les travailleurs autonomes ou les nouveaux arrivants au Canada peuvent-ils être admissibles?",
    "home_faq7_a": "Oui. Les emprunteurs autonomes peuvent être admissibles en utilisant deux années de déclarations de revenus et d'états financiers d'entreprise, ou grâce à des programmes à revenu déclaré auprès de prêteurs alternatifs. Les nouveaux arrivants ayant un historique de crédit canadien limité peuvent être admissibles grâce à des programmes hypothécaires dédiés aux nouveaux arrivants, souvent avec aussi peu que 5 à 10 % de mise de fonds.",
    "home_faq8_q": "Combien de temps prend l'approbation hypothécaire?",
    "home_faq8_a": "Une préapprobation peut souvent être obtenue en 24 à 48 heures une fois vos documents reçus. L'approbation complète après une offre signée, une fois l'évaluation et la souscription terminées, prend habituellement de 5 à 10 jours ouvrables, bien que les dossiers commerciaux ou d'entreprise complexes puissent prendre plus de temps.",
    "home_glossary_title": "Des termes simples avant une grande décision.",
    "home_term1_a": "Un examen par le prêteur qui vous aide à comprendre votre capacité d'emprunt avant de faire une offre.",
    "home_term2_a": "Remplacer ou ajuster une hypothèque existante pour accéder à la valeur nette, consolider des dettes ou modifier les conditions.",
    "home_term3_q": "Prêteur alternatif",
    "home_term3_a": "Un prêteur en dehors des critères bancaires traditionnels, souvent utile pour les travailleurs autonomes, les revenus atypiques ou les dossiers complexes.",
    "home_cta_title": "De vraies personnes. Une aide réelle. De vrais résultats.",
    "home_cta_desc": "Royal Den dispose d'une équipe d'experts qui peut vous aider à bâtir un avenir sûr et prospère tout en gérant les détails financiers complexes.",
