    "home_d1_q": "Taux affichés sur ce site",
    "home_d1_a": "Les taux affichés sont à titre indicatif et peuvent changer sans préavis. Ils ne sont pas garantis et ne constituent pas une garantie de taux ou un engagement tant qu'ils n'ont pas été confirmés par écrit par un prêteur.",
    "home_d2_q": "L'approbation n'est pas garantie",
    "home_d2_a": "Toutes les hypothèques demeurent assujetties aux critères de prêt habituels, y compris la vérification du revenu, l'approbation du crédit et l'évaluation de la propriété (sous réserve d'approbation de crédit). Les conditions finales sont établies par le prêteur, et non par Royal Den Capital.",
    "home_d3_q": "Estimations du calculateur",
    "home_d3_a": "Les chiffres de paiement hypothécaire, de prime d'assurance et de taxe de mutation produits par le calculateur de ce site sont des estimations indicatives seulement et peuvent ne pas refléter vos coûts réels. Les primes d'assurance et la taxe de mutation sont établies par les assureurs et par les gouvernements provinciaux/municipaux et peuvent changer.",
    "home_d4_q": "Comment nous sommes rémunérés",
    "home_d4_a": "En tant que courtage hypothécaire agréé, Royal Den Capital peut recevoir une rémunération (frais de recherche ou commissions) des prêteurs pour les hypothèques que nous plaçons. Cela n'augmente pas votre taux ou votre coût et n'affecte pas l'impartialité des conseils que vous recevez.",
    "home_d5_q": "Licence",
    "home_d5_a": "Royal Den Capital exerce ses activités sous le permis de courtier hypothécaire n° M08000511 et le permis Mortgage Alliance Ontario n° 10530. Royal Den Capital est une entreprise détenue et exploitée de façon indépendante.",
    "home_d6_q": "Ne constitue pas un conseil financier, juridique ou fiscal",
