    "home_d7_q": "Disponibilité par région",
    "home_d7_a": "Tous les prêteurs, produits ou programmes mentionnés sur ce site ne sont pas disponibles dans toutes les provinces ni pour tous les types de propriétés. La disponibilité dépend du prêteur et de votre admissibilité individuelle.",
    "home_d8_q": "Erreurs et omissions",
    "home_d8_a": "E&OE — sauf erreurs et omissions. Bien que nous nous efforcions de maintenir ce site exact et à jour, les taux, programmes et chiffres mentionnés peuvent changer; contactez-nous directement pour confirmer toute information avant de vous y fier.",
    "home_chat_button": "Clavardage en direct",
    "home_newsletter_desc": "Inscrivez-vous pour recevoir des conseils hypothécaires, des mises à jour de taux et des informations de financement de Royal Den Capital.",
