    "cr_look_li2": "De solides habitudes de communication et de suivi.",
    "cr_look_li3": "À l'aise pour discuter des taux, paiements, documents, échéanciers, et objectifs des clients.",
    "cr_look_li4": "Capacité de prospecter, réseauter, et bâtir des relations de référence.",
    "cr_look_li5": "Discipline professionnelle avec l'information confidentielle des clients.",
    "cr_workon_h3": "Sur quoi vous pouvez travailler",
    "cr_wo_li1": "Dossiers d'achat et de préapprobation.",
    "cr_wo_li2": "Refinancements, renouvellements, marges de crédit, et retraits de capital propre.",
    "cr_wo_li3": "Scénarios de prêt pour nouveaux arrivants, travailleurs autonomes, et alternatifs.",
    "cr_wo_li4": "Opportunités commerciales et de construction à mesure que l'expérience grandit.",
    "cr_std_kicker": "La norme RDC",
    "cr_std_h2": "Travail indépendant, attentes professionnelles.",
    "cr_std_p": "Le travail hypothécaire à commission récompense l'initiative. Nous recherchons des personnes qui vont jusqu'au bout, protègent la confiance des clients, et font avancer les dossiers avec soin.",
    "cr_s1_h3": "Assumez le suivi",
    "cr_s1_p": "Les clients et les partenaires de référence devraient toujours savoir ce qui se passe ensuite, ce qui manque, et quand ils auront de vos nouvelles.",
    "cr_s2_h3": "Respectez le dossier",
    "cr_s2_p": "Les conseils hypothécaires dépendent de détails financiers privés. Nous attendons une manipulation soigneuse des documents, notes, conditions du prêteur, et conversations avec les clients.",
    "cr_s3_h3": "Bâtissez votre marché",
    "cr_s3_p": "Les agents les plus performants créent des opportunités grâce au réseautage, aux références, à la présence locale, et à l'éducation constante des clients.",
    "cr_faq_kicker": "Questions de carrière",
    "cr_faq_h2": "Avant de postuler.",
    "cr_faq_p": "Utilisez cet aperçu rapide pour décider si l'opportunité correspond à la façon dont vous voulez travailler.",
    "cr_faq1_q": "S'agit-il d'un poste salarié?",
    "cr_faq1_a": "Non. Il s'agit d'une opportunité à commission pour les personnes à l'aise de développer des affaires et de gagner de l'argent grâce à des dossiers hypothécaires financés.",
    "cr_faq2_q": "Dois-je déjà être agréé?",
    "cr_faq2_a": "Les agents et courtiers agréés sont encouragés à postuler. Si vous êtes en train de compléter votre licence, vous pouvez quand même vous présenter et partager votre échéancier.",
