    "home_rates_desc": "ਕੈਨੇਡਾ ਭਰ ਦੇ ਭਰੋਸੇਯੋਗ ਰਿਣਦਾਤਿਆਂ ਦੀਆਂ ਪੇਸ਼ਕਸ਼ਾਂ ਦੀ ਤੁਲਨਾ ਕਰੋ। ਇੱਕ ਮੌਰਗੇਜ ਦਰ ਪ੍ਰਾਪਤ ਕਰੋ ਜੋ ਤੁਹਾਡੇ ਟੀਚਿਆਂ ਦੇ ਅਨੁਕੂਲ ਹੋਵੇ ਅਤੇ ਪੈਸੇ ਬਚਾਏ।",
