    "home_disclosures_title": "ਦਰਾਂ, ਸ਼ਰਤਾਂ ਅਤੇ ਮਹੱਤਵਪੂਰਨ ਖੁਲਾਸੇ",
    "home_d1_q": "ਇਸ ਸਾਈਟ 'ਤੇ ਦਿਖਾਈਆਂ ਦਰਾਂ",
    "home_d1_a": "ਦਿਖਾਈਆਂ ਗਈਆਂ ਦਰਾਂ ਸਿਰਫ਼ ਉਦਾਹਰਨ ਲਈ ਹਨ ਅਤੇ ਬਿਨਾਂ ਸੂਚਨਾ ਦੇ ਬਦਲ ਸਕਦੀਆਂ ਹਨ। ਇਹ ਗਾਰੰਟੀਸ਼ੁਦਾ ਨਹੀਂ ਹਨ ਅਤੇ ਜਦੋਂ ਤੱਕ ਕਿਸੇ ਰਿਣਦਾਤਾ ਦੁਆਰਾ ਲਿਖਤੀ ਰੂਪ ਵਿੱਚ ਪੁਸ਼ਟੀ ਨਹੀਂ ਕੀਤੀ ਜਾਂਦੀ, ਇਹ ਦਰ ਹੋਲਡ ਜਾਂ ਵਚਨਬੱਧਤਾ ਨਹੀਂ ਬਣਾਉਂਦੀਆਂ।",
    "home_d2_q": "ਮਨਜ਼ੂਰੀ ਦੀ ਗਰੰਟੀ ਨਹੀਂ ਹੈ",
    "home_d2_a": "ਸਾਰੀਆਂ ਮੌਰਗੇਜਾਂ ਮਿਆਰੀ ਰਿਣ ਮਾਪਦੰਡਾਂ ਦੇ ਅਧੀਨ ਰਹਿੰਦੀਆਂ ਹਨ, ਜਿਸ ਵਿੱਚ ਆਮਦਨ ਪੁਸ਼ਟੀ, ਕ੍ਰੈਡਿਟ ਮਨਜ਼ੂਰੀ, ਅਤੇ ਜਾਇਦਾਦ ਮੁਲਾਂਕਣ ਸ਼ਾਮਲ ਹੈ (ਮਨਜ਼ੂਰਸ਼ੁਦਾ ਕ੍ਰੈਡਿਟ 'ਤੇ)। ਅੰਤਿਮ ਸ਼ਰਤਾਂ ਰਿਣਦਾਤੇ ਦੁਆਰਾ ਤੈਅ ਕੀਤੀਆਂ ਜਾਂਦੀਆਂ ਹਨ, Royal Den Capital ਦੁਆਰਾ ਨਹੀਂ।",
    "home_d3_q": "ਕੈਲਕੁਲੇਟਰ ਅਨੁਮਾਨ",
    "home_d3_a": "ਇਸ ਸਾਈਟ 'ਤੇ ਕੈਲਕੁਲੇਟਰ ਦੁਆਰਾ ਤਿਆਰ ਕੀਤੇ ਮੌਰਗੇਜ ਭੁਗਤਾਨ, ਬੀਮਾ ਪ੍ਰੀਮੀਅਮ, ਅਤੇ ਭੂਮੀ ਟ੍ਰਾਂਸਫਰ ਟੈਕਸ ਦੇ ਅੰਕੜੇ ਸਿਰਫ਼ ਉਦਾਹਰਨ ਅਨੁਮਾਨ ਹਨ ਅਤੇ ਹੋ ਸਕਦਾ ਹੈ ਤੁਹਾਡੀਆਂ ਅਸਲ ਲਾਗਤਾਂ ਨੂੰ ਨਾ ਦਰਸਾਉਣ। ਬੀਮਾ ਪ੍ਰੀਮੀਅਮ ਅਤੇ ਭੂਮੀ ਟ੍ਰਾਂਸਫਰ ਟੈਕਸ ਬੀਮਾਕਰਤਾਵਾਂ ਅਤੇ ਸੂਬਾਈ/ਮਿਉਂਸਿਪਲ ਸਰਕਾਰਾਂ ਦੁਆਰਾ ਤੈਅ ਕੀਤੇ ਜਾਂਦੇ ਹਨ ਅਤੇ ਬਦਲ ਸਕਦੇ ਹਨ।",
    "home_d4_q": "ਸਾਨੂੰ ਕਿਵੇਂ ਭੁਗਤਾਨ ਕੀਤਾ ਜਾਂਦਾ ਹੈ",
    "home_d4_a": "ਇੱਕ ਲਾਇਸੰਸਸ਼ੁਦਾ ਮੌਰਗੇਜ ਬ੍ਰੋਕਰੇਜ ਵਜੋਂ, Royal Den Capital ਨੂੰ ਅਸੀਂ ਲਗਾਈਆਂ ਮੌਰਗੇਜਾਂ ਲਈ ਰਿਣਦਾਤਿਆਂ ਤੋਂ ਮੁਆਵਜ਼ਾ (ਖੋਜ ਫੀਸ ਜਾਂ ਕਮਿਸ਼ਨ) ਮਿਲ ਸਕਦਾ ਹੈ। ਇਹ ਤੁਹਾਡੀ ਦਰ ਜਾਂ ਲਾਗਤ ਵਿੱਚ ਵਾਧਾ ਨਹੀਂ ਕਰਦਾ ਅਤੇ ਤੁਹਾਨੂੰ ਮਿਲਣ ਵਾਲੀ ਸਲਾਹ ਦੀ ਨਿਰਪੱਖਤਾ ਨੂੰ ਪ੍ਰਭਾਵਿਤ ਨਹੀਂ ਕਰਦਾ।",
    "home_d5_q": "ਲਾਇਸੈਂਸਿੰਗ",
    "home_d5_a": "Royal Den Capital ਮੌਰਗੇਜ ਬ੍ਰੋਕਰ ਲਾਇਸੈਂਸ ਨੰ. M08000511 ਅਤੇ ਮੌਰਗੇਜ ਅਲਾਇੰਸ ਓਨਟਾਰੀਓ ਲਾਇਸੈਂਸ ਨੰ. 10530 ਅਧੀਨ ਕੰਮ ਕਰਦਾ ਹੈ। Royal Den Capital ਸੁਤੰਤਰ ਤੌਰ 'ਤੇ ਮਾਲਕੀ ਅਤੇ ਸੰਚਾਲਿਤ ਹੈ।",
    "home_d6_q": "ਵਿੱਤੀ, ਕਾਨੂੰਨੀ, ਜਾਂ ਟੈਕਸ ਸਲਾਹ ਨਹੀਂ",
    "home_d6_a": "ਇਸ ਵੈੱਬਸਾਈਟ 'ਤੇ ਸਮੱਗਰੀ, ਜਿਸ ਵਿੱਚ ਸ਼ਬਦਾਵਲੀ, ਸਵਾਲ-ਜਵਾਬ, ਅਤੇ ਪ੍ਰਕਿਰਿਆ ਗਾਈਡ ਸ਼ਾਮਲ ਹਨ, ਸਿਰਫ਼ ਆਮ ਵਿਦਿਅਕ ਉਦੇਸ਼ਾਂ ਲਈ ਦਿੱਤੀ ਗਈ ਹੈ ਅਤੇ ਵਿੱਤੀ, ਕਾਨੂੰਨੀ, ਜਾਂ ਟੈਕਸ ਸਲਾਹ ਨਹੀਂ ਬਣਦੀ। ਫੈਸਲੇ ਲੈਣ ਤੋਂ ਪਹਿਲਾਂ ਆਪਣੀ ਖਾਸ ਸਥਿਤੀ ਬਾਰੇ ਇੱਕ ਲਾਇਸੰਸਸ਼ੁਦਾ ਸਲਾਹਕਾਰ ਨਾਲ ਗੱਲ ਕਰੋ।",
    "home_d7_q": "ਖੇਤਰ ਅਨੁਸਾਰ ਉਪਲਬਧਤਾ",
    "home_d7_a": "ਇਸ ਸਾਈਟ 'ਤੇ ਦਰਸਾਏ ਸਾਰੇ ਰਿਣਦਾਤੇ, ਉਤਪਾਦ, ਜਾਂ ਪ੍ਰੋਗਰਾਮ ਹਰ ਸੂਬੇ ਵਿੱਚ ਜਾਂ ਹਰ ਜਾਇਦਾਦ ਕਿਸਮ ਲਈ ਉਪਲਬਧ ਨਹੀਂ ਹਨ। ਉਪਲਬਧਤਾ ਰਿਣਦਾਤੇ ਅਤੇ ਤੁਹਾਡੀ ਵਿਅਕਤੀਗਤ ਯੋਗਤਾ 'ਤੇ ਨਿਰਭਰ ਕਰਦੀ ਹੈ।",
    "home_d8_q": "ਗਲਤੀਆਂ ਅਤੇ ਭੁੱਲਾਂ",
    "home_d8_a": "E&OE — ਗਲਤੀਆਂ ਅਤੇ ਭੁੱਲਾਂ ਨੂੰ ਛੱਡ ਕੇ। ਭਾਵੇਂ ਅਸੀਂ ਇਸ ਸਾਈਟ ਨੂੰ ਸਹੀ ਅਤੇ ਅੱਪ-ਟੂ-ਡੇਟ ਰੱਖਣ ਦੀ ਕੋਸ਼ਿਸ਼ ਕਰਦੇ ਹਾਂ, ਦਰਸਾਈਆਂ ਦਰਾਂ, ਪ੍ਰੋਗਰਾਮ, ਅਤੇ ਅੰਕੜੇ ਬਦਲ ਸਕਦੇ ਹਨ; ਇਸ 'ਤੇ ਭਰੋਸਾ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਕਿਸੇ ਵੀ ਚੀਜ਼ ਦੀ ਪੁਸ਼ਟੀ ਕਰਨ ਲਈ ਸਿੱਧੇ ਸਾਡੇ ਨਾਲ ਸੰਪਰਕ ਕਰੋ।",
    "home_chat_button": "ਲਾਈਵ ਚੈਟ",
    "home_newsletter_desc": "Royal Den Capital ਤੋਂ ਮੌਰਗੇਜ ਸੁਝਾਅ, ਦਰ ਅੱਪਡੇਟ, ਅਤੇ ਫੰਡਿੰਗ ਜਾਣਕਾਰੀ ਲਈ ਸਾਈਨ ਅੱਪ ਕਰੋ।",
    "home_newsletter_name_ph": "ਨਾਮ",
    "home_newsletter_email_ph": "ਈਮੇਲ",
    "home_newsletter_signup": "ਸਾਈਨ ਅੱਪ ਕਰੋ",
    "fsms_hero_kicker": "ਮੌਰਗੇਜ ਜਾਣਕਾਰੀ",
    "fsms_hero_title": "ਮੌਰਗੇਜ ਹੱਲ, ਸਰਲ ਤਰੀਕੇ ਨਾਲ ਸਮਝਾਏ ਗਏ।",
    "fsms_hero_lead": "ਇਸ ਪੰਨੇ ਨੂੰ ਏਜੰਟਾਂ ਅਤੇ ਗਾਹਕਾਂ ਲਈ ਇੱਕ ਤੇਜ਼ ਹਵਾਲੇ ਵਜੋਂ ਵਰਤੋ। ਇਹ ਮੁੱਖ ਮੌਰਗੇਜ ਰਸਤਿਆਂ, ਹਰੇਕ ਕਦੋਂ ਢੁਕਵਾਂ ਹੈ, ਕੀ ਇਕੱਠਾ ਕਰਨਾ ਹੈ, ਅਤੇ ਅੱਗੇ ਕਿੱਥੇ ਜਾਣਾ ਹੈ, ਦੀ ਰੂਪਰੇਖਾ ਦਿੰਦਾ ਹੈ।",
    "fsms_start_app": "ਅਰਜ਼ੀ ਸ਼ੁਰੂ ਕਰੋ",
    "fsms_mortgage_calc": "ਮੌਰਗੇਜ ਕੈਲਕੁਲੇਟਰ",
    "fsms_on_this_page": "ਇਸ ਪੰਨੇ 'ਤੇ",
    "fsms_idx_options": "ਮੌਰਗੇਜ ਵਿਕਲਪ",
    "fsms_idx_fixed_variable": "ਫਿਕਸਡ ਬਨਾਮ ਵੇਰੀਏਬਲ",
    "fsms_idx_open_closed": "ਓਪਨ ਬਨਾਮ ਕਲੋਜ਼ਡ",
