    "fsms_idx_documents": "ਦਸਤਾਵੇਜ਼",
    "fsms_idx_tools": "ਟੂਲ ਅਤੇ ਲਿੰਕ",
    "fsms_options_kicker": "ਮੌਰਗੇਜ ਵਿਕਲਪ",
    "fsms_options_title": "ਪਹਿਲਾਂ ਫਾਈਲ ਦੀ ਕਿਸਮ ਚੁਣੋ।",
    "fsms_options_desc": "ਜ਼ਿਆਦਾਤਰ ਮੌਰਗੇਜ ਗੱਲਬਾਤ ਆਸਾਨ ਹੋ ਜਾਂਦੀ ਹੈ ਇੱਕ ਵਾਰ ਏਜੰਟ ਗਾਹਕ ਦੀ ਸਥਿਤੀ ਦੀ ਪਛਾਣ ਕਰ ਲੈਂਦਾ ਹੈ। ਗਾਹਕਾਂ ਨੂੰ ਸਹੀ ਹੱਲ ਪੰਨੇ 'ਤੇ ਭੇਜਣ ਅਤੇ ਫਾਈਲ ਜਮ੍ਹਾਂ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਸਹੀ ਸੰਦਰਭ ਇਕੱਠਾ ਕਰਨ ਲਈ ਹੇਠਾਂ ਦਿੱਤੀ ਸੂਚੀ ਦੀ ਵਰਤੋਂ ਕਰੋ।",
    "fsms_second_home_title": "ਦੂਜਾ ਘਰ ਜਾਂ ਅਗਲਾ ਘਰ",
    "fsms_heloc_title": "ਹੋਮ ਇਕੁਇਟੀ ਲਾਈਨ ਆਫ਼ ਕ੍ਰੈਡਿਟ",
    "fsms_newcomer_title": "ਕੈਨੇਡਾ ਵਿੱਚ ਨਵੇਂ ਲਈ ਮੌਰਗੇਜ",
    "fsms_first_time_desc": "ਖਰੀਦਦਾਰਾਂ ਲਈ ਜੋ ਪਹਿਲੀ ਵਾਰ ਮਾਰਕੀਟ ਵਿੱਚ ਦਾਖਲ ਹੋ ਰਹੇ ਹਨ। ਡਾਊਨ ਪੇਮੈਂਟ ਸਰੋਤ, ਆਮਦਨ ਸਥਿਰਤਾ, ਕ੍ਰੈਡਿਟ ਇਤਿਹਾਸ, ਖਰੀਦ ਬਜਟ, ਅਤੇ ਕੀ ਉਹ ਪਹਿਲੀ ਵਾਰ ਖਰੀਦਦਾਰ ਪ੍ਰੋਗਰਾਮਾਂ ਜਾਂ ਛੋਟਾਂ ਲਈ ਯੋਗ ਹੋ ਸਕਦੇ ਹਨ, ਦੀ ਪੁਸ਼ਟੀ ਕਰੋ।",
    "fsms_second_home_desc": "ਗਾਹਕਾਂ ਲਈ ਜੋ ਅੱਪਗ੍ਰੇਡ ਕਰ ਰਹੇ ਹਨ, ਡਾਊਨਸਾਈਜ਼ ਕਰ ਰਹੇ ਹਨ, ਜਾਂ ਛੁੱਟੀਆਂ/ਸੈਕੰਡਰੀ ਜਾਇਦਾਦ ਖਰੀਦ ਰਹੇ ਹਨ। ਵਿਕਰੀ ਸਮਾਂ, ਬ੍ਰਿਜ ਵਿੱਤ ਲੋੜਾਂ, ਪੋਰਟਿੰਗ ਵਿਕਲਪ, ਅਤੇ ਕੁੱਲ ਕੈਰੀਿੰਗ ਲਾਗਤਾਂ ਦੀ ਸਮੀਖਿਆ ਕਰੋ।",
    "fsms_refinance_desc": "ਘਰ ਮਾਲਕਾਂ ਲਈ ਜੋ ਇਕੁਇਟੀ ਤੱਕ ਪਹੁੰਚ ਕਰਨ, ਕਰਜ਼ਾ ਇਕਸਾਰ ਕਰਨ, ਰਿਣਦਾਤਾ ਬਦਲਣ, ਜਾਂ ਨਕਦ ਪ੍ਰਵਾਹ ਸੁਧਾਰਨ ਲਈ ਮੌਜੂਦਾ ਮੌਰਗੇਜ ਬਦਲ ਰਹੇ ਹਨ। ਮੌਜੂਦਾ ਬਕਾਇਆ, ਮਿਆਦ ਪੂਰੀ ਹੋਣ ਦੀ ਮਿਤੀ, ਜੁਰਮਾਨਾ ਅਨੁਮਾਨ, ਜਾਇਦਾਦ ਮੁੱਲ, ਅਤੇ ਕਰਜ਼ਾ ਭੁਗਤਾਨ ਸੂਚੀ ਦੀ ਜਾਂਚ ਕਰੋ।",
    "fsms_renovation_desc": "ਘਰ ਮਾਲਕਾਂ ਜਾਂ ਖਰੀਦਦਾਰਾਂ ਲਈ ਜੋ ਮੁਰੰਮਤ ਅਤੇ ਅੱਪਗ੍ਰੇਡ ਲਈ ਫੰਡ ਦਿੰਦੇ ਹਨ। ਰੀਨੋਵੇਸ਼ਨ ਬਜਟ, ਠੇਕੇਦਾਰ ਅਨੁਮਾਨ, ਇਕੁਇਟੀ ਸਥਿਤੀ, ਅਤੇ ਕੀ ਰੀਫਾਈਨੈਂਸ, HELOC, ਦੂਜੀ ਮੌਰਗੇਜ, ਜਾਂ ਖਰੀਦ-ਪਲੱਸ-ਸੁਧਾਰ ਰਸਤਾ ਸਭ ਤੋਂ ਵਧੀਆ ਢੁਕਵਾਂ ਹੈ, ਦੀ ਪੁਸ਼ਟੀ ਕਰੋ।",
    "fsms_renewal_desc": "ਗਾਹਕਾਂ ਲਈ ਜੋ ਮਿਆਦ ਪੂਰੀ ਹੋਣ ਦੇ ਨੇੜੇ ਹਨ। ਨਵਿਆਉਣ ਦੀ ਪੇਸ਼ਕਸ਼, ਮੌਜੂਦਾ ਰਿਣਦਾਤਾ, ਬਾਕੀ ਬਕਾਇਆ, ਮਿਆਦ ਪੂਰੀ ਹੋਣ ਦੀ ਮਿਤੀ, ਭੁਗਤਾਨ ਆਰਾਮ, ਅਤੇ ਅਗਲੀ ਮਿਆਦ ਲਈ ਟੀਚੇ ਪੁੱਛੋ।",
    "fsms_equity_takeout_desc": "ਗਾਹਕਾਂ ਲਈ ਜੋ ਵੇਚੇ ਬਿਨਾਂ ਘਰ ਦੀ ਇਕੁਇਟੀ ਤੋਂ ਨਕਦ ਚਾਹੁੰਦੇ ਹਨ। ਫੰਡਾਂ ਦੀ ਵਰਤੋਂ, ਮੌਜੂਦਾ ਮੌਰਗੇਜ ਵੇਰਵੇ, ਜਾਇਦਾਦ ਮੁੱਲ, ਕ੍ਰੈਡਿਟ ਪ੍ਰੋਫਾਈਲ, ਅਤੇ ਕੀ ਭੁਗਤਾਨ ਅਸਥਾਈ ਜਾਂ ਲੰਬੇ ਸਮੇਂ ਲਈ ਹੈ, ਸਪੱਸ਼ਟ ਕਰੋ।",
    "fsms_heloc_desc": "ਸਮੇਂ ਦੇ ਨਾਲ ਇਕੁਇਟੀ ਤੱਕ ਲਚਕਦਾਰ ਪਹੁੰਚ ਲਈ। ਚੱਲ ਰਹੇ ਪ੍ਰੋਜੈਕਟਾਂ, ਐਮਰਜੈਂਸੀ ਤਰਲਤਾ, ਨਿਵੇਸ਼ ਮੌਕਿਆਂ, ਜਾਂ ਪੜਾਅਵਾਰ ਖਰਚਿਆਂ ਲਈ ਲਾਭਦਾਇਕ।",
    "fsms_debt_desc": "ਗਾਹਕਾਂ ਲਈ ਜੋ ਉੱਚ-ਵਿਆਜ ਵਾਲੇ ਕ੍ਰੈਡਿਟ ਕਾਰਡ, ਲੋਨ, ਜਾਂ ਕ੍ਰੈਡਿਟ ਲਾਈਨਾਂ ਚੁੱਕਦੇ ਹਨ। ਬਕਾਇਆ, ਮਹੀਨਾਵਾਰ ਭੁਗਤਾਨ, ਵਿਆਜ ਦਰਾਂ, ਅਤੇ ਜਿੱਥੇ ਉਪਲਬਧ ਹੋਵੇ ਭੁਗਤਾਨ ਸਟੇਟਮੈਂਟਾਂ ਇਕੱਠੀਆਂ ਕਰੋ।",
    "fsms_reverse_desc": "ਵੱਡੀ ਉਮਰ ਦੇ ਘਰ ਮਾਲਕਾਂ ਲਈ ਜੋ ਜਾਇਦਾਦ ਵਿੱਚ ਰਹਿੰਦੇ ਹੋਏ ਇਕੁਇਟੀ ਤੱਕ ਪਹੁੰਚ ਕਰਨਾ ਚਾਹੁੰਦੇ ਹਨ। ਉਮਰ, ਮਾਲਕੀ, ਜਾਇਦਾਦ ਕਿਸਮ, ਮੌਜੂਦਾ ਮੌਰਗੇਜ ਬਕਾਇਆ, ਅਤੇ ਲੰਬੇ ਸਮੇਂ ਦੀਆਂ ਯੋਜਨਾਵਾਂ ਦੀ ਪੁਸ਼ਟੀ ਕਰੋ।",
    "fsms_newcomer_desc": "ਨਵੇਂ ਆਏ ਲੋਕਾਂ ਲਈ ਸੀਮਿਤ ਕੈਨੇਡੀਅਨ ਕ੍ਰੈਡਿਟ ਇਤਿਹਾਸ ਨਾਲ। ਨਿਵਾਸ ਸਥਿਤੀ, ਰੁਜ਼ਗਾਰ, ਡਾਊਨ ਪੇਮੈਂਟ ਸਰੋਤ, ਅੰਤਰਰਾਸ਼ਟਰੀ ਕ੍ਰੈਡਿਟ ਹਵਾਲੇ, ਅਤੇ ਬੈਂਕ ਸਟੇਟਮੈਂਟਾਂ ਦੀ ਸਮੀਖਿਆ ਕਰੋ।",
    "fsms_construction_desc": "ਕਸਟਮ ਬਿਲਡਾਂ, ਵੱਡੀ ਉਸਾਰੀ, ਅਤੇ ਪੜਾਅਵਾਰ ਫੰਡਿੰਗ ਲਈ। ਜ਼ਮੀਨ ਵੇਰਵੇ, ਪਰਮਿਟ, ਬਜਟ, ਬਿਲਡਰ ਜਾਣਕਾਰੀ, ਡਰਾਅ ਸ਼ਡਿਊਲ, ਅਤੇ ਮੁਲਾਂਕਣ ਉਮੀਦਾਂ ਇਕੱਠੀਆਂ ਕਰੋ।",
    "fsms_commercial_desc": "ਮਾਲਕ-ਕਬਜ਼ੇ ਵਾਲੀ ਜਾਂ ਆਮਦਨ ਪੈਦਾ ਕਰਨ ਵਾਲੀ ਕਮਰਸ਼ੀਅਲ ਜਾਇਦਾਦ ਲਈ। ਵਪਾਰਕ ਵਿੱਤ, ਲੀਜ਼ ਆਮਦਨ, ਜਾਇਦਾਦ ਕਿਸਮ, ਵਾਤਾਵਰਣ ਲੋੜਾਂ, ਅਤੇ ਡਾਊਨ ਪੇਮੈਂਟ ਤਾਕਤ ਦੀ ਸਮੀਖਿਆ ਕਰੋ।",
    "fsms_purchase_improve_desc": "ਖਰੀਦਦਾਰਾਂ ਲਈ ਜੋ ਅਜਿਹਾ ਘਰ ਖਰੀਦ ਰਹੇ ਹਨ ਜਿਸ ਨੂੰ ਤੁਰੰਤ ਅੱਪਗ੍ਰੇਡ ਦੀ ਲੋੜ ਹੈ। ਸਵੀਕਾਰਿਆ ਖਰੀਦ ਮੁੱਲ, ਸੁਧਾਰ ਕੋਟ, ਡਾਊਨ ਪੇਮੈਂਟ, ਰਿਣਦਾਤਾ ਨਿਯਮ, ਅਤੇ ਪੂਰਾ ਹੋਣ ਦਾ ਸਮਾਂ ਪੁਸ਼ਟੀ ਕਰੋ।",
    "fsms_co_equity_desc": "ਖਰੀਦਦਾਰਾਂ ਲਈ ਜੋ ਸਮਰੱਥਾ ਸੁਧਾਰਨ ਲਈ ਸਾਂਝੀ-ਇਕੁਇਟੀ ਸਹਾਇਤਾ ਦੀ ਖੋਜ ਕਰ ਰਹੇ ਹਨ। ਯੋਗਤਾ, ਯੋਗਦਾਨ ਉਮੀਦਾਂ, ਭਵਿੱਖੀ ਵਿਕਰੀ ਨਿਯਮ, ਅਤੇ ਲੰਬੇ ਸਮੇਂ ਦੇ ਮਾਲਕੀ ਟੀਚਿਆਂ ਦੀ ਸਮੀਖਿਆ ਕਰੋ।",
    "fsms_rate_kicker": "ਦਰ ਢਾਂਚਾ",
    "fsms_rate_title": "ਫਿਕਸਡ ਬਨਾਮ ਵੇਰੀਏਬਲ।",
    "fsms_fixed_rate_h3": "ਫਿਕਸਡ ਦਰ",
    "fsms_fixed_rate_p": "ਪੂਰੀ ਮਿਆਦ ਲਈ ਵਿਆਜ ਦਰ ਇੱਕੋ ਜਿਹੀ ਰਹਿੰਦੀ ਹੈ। ਇਹ ਉਹਨਾਂ ਗਾਹਕਾਂ ਲਈ ਆਸਾਨ ਹੈ ਜੋ ਅਨੁਮਾਨਯੋਗ ਭੁਗਤਾਨ ਅਤੇ ਬਜਟ ਨਿਸ਼ਚਿਤਤਾ ਚਾਹੁੰਦੇ ਹਨ।",
    "fsms_fixed_li1": "ਸਥਿਰ ਮਹੀਨਾਵਾਰ ਯੋਜਨਾਬੰਦੀ ਲਈ ਸਭ ਤੋਂ ਵਧੀਆ।",
