    "gl_flow_4_d": "ਰਿਣਦਾਤਾ ਸਮੀਖਿਆ, ਮੁਲਾਂਕਣ, ਸ਼ਰਤਾਂ",
    "gl_flow_5_t": "ਕਲੋਜ਼ਿੰਗ",
    "gl_flow_5_d": "ਵਕੀਲ, ਫੰਡ, ਟਾਈਟਲ, ਚਾਬੀਆਂ",
    "gl_flow_6_t": "ਨਵਿਆਉਣ",
    "gl_flow_6_d": "ਦਰ, ਮਿਆਦ, ਰਿਣਦਾਤਾ, ਰਣਨੀਤੀ ਦੀ ਸਮੀਖਿਆ ਕਰੋ",
    "gl_three_numbers_h3": "ਤਿੰਨ ਅੰਕੜੇ ਜ਼ਿਆਦਾਤਰ ਮੌਰਗੇਜ ਫੈਸਲਿਆਂ ਨੂੰ ਆਕਾਰ ਦਿੰਦੇ ਹਨ",
    "gl_num1_strong": "ਖਰੀਦ ਮੁੱਲ ਜਾਂ ਜਾਇਦਾਦ ਮੁੱਲ:",
    "gl_num1_rest": " ਖਰੀਦ ਲਈ ਭੁਗਤਾਨ ਕੀਤਾ ਜਾ ਰਿਹਾ ਮੁੱਲ, ਜਾਂ ਰੀਫਾਈਨੈਂਸ ਕਰਨ ਵੇਲੇ ਅਨੁਮਾਨਿਤ ਮਾਰਕੀਟ ਮੁੱਲ।",
    "gl_num2_strong": "ਮੌਰਗੇਜ ਰਕਮ:",
    "gl_num2_rest": " ਡਾਊਨ ਪੇਮੈਂਟ, ਇਕੁਇਟੀ, ਬੀਮਾ ਪ੍ਰੀਮੀਅਮ, ਰੀਫਾਈਨੈਂਸ ਫੰਡ, ਜਾਂ ਕਰਜ਼ਾ ਇਕਸਾਰੀਕਰਨ ਨੂੰ ਧਿਆਨ ਵਿੱਚ ਰੱਖਣ ਤੋਂ ਬਾਅਦ ਉਧਾਰ ਲਈ ਗਈ ਰਕਮ।",
    "gl_num3_strong": "ਭੁਗਤਾਨ ਆਰਾਮ:",
    "gl_num3_rest": " ਉਹ ਰਕਮ ਜੋ ਤੁਹਾਡਾ ਘਰ ਮੌਰਗੇਜ ਭੁਗਤਾਨ, ਜਾਇਦਾਦ ਟੈਕਸ, ਯੂਟਿਲਿਟੀਜ਼, ਬੀਮਾ, ਰੱਖ-ਰਖਾਅ, ਅਤੇ ਆਮ ਰਹਿਣ-ਸਹਿਣ ਦੀਆਂ ਲਾਗਤਾਂ ਤੋਂ ਬਾਅਦ ਸੰਭਾਲ ਸਕਦਾ ਹੈ।",
    "gl_process_kicker": "ਖਰੀਦ ਪ੍ਰਕਿਰਿਆ",
    "gl_process_h2": "ਮੌਰਗੇਜ ਪ੍ਰਕਿਰਿਆ ਕਿਵੇਂ ਕੰਮ ਕਰਦੀ ਹੈ",
    "gl_step1_h3": "ਆਪਣੀ ਫਾਈਲ ਤਿਆਰ ਕਰੋ",
    "gl_step1_p": "ਗੰਭੀਰਤਾ ਨਾਲ ਖਰੀਦਦਾਰੀ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ, ਆਮਦਨ ਦਸਤਾਵੇਜ਼, ਡਾਊਨ ਪੇਮੈਂਟ ਇਤਿਹਾਸ, ਕਰਜ਼ਾ ਜਾਣਕਾਰੀ, ਕ੍ਰੈਡਿਟ ਵੇਰਵੇ, ਅਤੇ ਇੱਕ ਇਮਾਨਦਾਰ ਮਹੀਨਾਵਾਰ ਬਜਟ ਸੰਗਠਿਤ ਕਰੋ। ਇੱਕ ਮਜ਼ਬੂਤ ਫਾਈਲ ਵਧੇਰੇ ਰਿਣਦਾਤਾ ਵਿਕਲਪ ਬਣਾਉਂਦੀ ਹੈ।",
    "gl_step1_li1": "ਰੁਜ਼ਗਾਰ ਪੱਤਰ, ਤਨਖਾਹ ਸਲਿੱਪਾਂ, T4, NOA, ਸਵੈ-ਰੁਜ਼ਗਾਰ ਹੋਣ 'ਤੇ ਵਪਾਰਕ ਵਿੱਤ।",
    "gl_step1_li2": "ਡਾਊਨ ਪੇਮੈਂਟ ਸਰੋਤ ਅਤੇ ਡਿਪਾਜ਼ਿਟ ਇਤਿਹਾਸ ਦਿਖਾਉਂਦੀਆਂ ਬੈਂਕ ਸਟੇਟਮੈਂਟਾਂ।",
    "gl_step1_li3": "ਕਰਜ਼ਿਆਂ, ਲੋਨਾਂ, ਲੀਜ਼ਾਂ, ਸਹਾਇਤਾ ਭੁਗਤਾਨਾਂ, ਅਤੇ ਮੌਜੂਦਾ ਜਾਇਦਾਦਾਂ ਲਈ ਵੇਰਵੇ।",
    "gl_step2_h3": "ਪ੍ਰੀ-ਅਪਰੂਵ ਹੋਵੋ",
    "gl_step2_p": "ਇੱਕ ਪ੍ਰੀ-ਅਪਰੂਵਲ ਪੇਸ਼ਕਸ਼ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਅਨੁਮਾਨ ਲਗਾਉਂਦੀ ਹੈ ਕਿ ਤੁਸੀਂ ਕਿੰਨੇ ਲਈ ਯੋਗ ਹੋ ਸਕਦੇ ਹੋ। ਇਸ ਵਿੱਚ ਦਰ ਹੋਲਡ ਸ਼ਾਮਲ ਹੋ ਸਕਦੀ ਹੈ, ਪਰ ਇਹ ਅੰਤਿਮ ਮਨਜ਼ੂਰੀ ਨਹੀਂ ਹੈ ਕਿਉਂਕਿ ਜਾਇਦਾਦ ਅਤੇ ਅੱਪਡੇਟ ਕੀਤੇ ਦਸਤਾਵੇਜ਼ਾਂ ਨੂੰ ਅਜੇ ਵੀ ਰਿਣਦਾਤਾ ਸਮੀਖਿਆ ਦੀ ਲੋੜ ਹੈ।",
    "gl_step3_h3": "ਸਹੀ ਸ਼ਰਤਾਂ ਨਾਲ ਪੇਸ਼ਕਸ਼ ਕਰੋ",
    "gl_step3_p": "ਜਦੋਂ ਸੰਭਵ ਹੋਵੇ, ਵਿੱਤ, ਨਿਰੀਖਣ, ਬੀਮਾ, ਅਤੇ ਕਾਨੂੰਨੀ ਸਮੀਖਿਆ ਸ਼ਰਤਾਂ ਨਾਲ ਆਪਣੇ ਆਪ ਨੂੰ ਸੁਰੱਖਿਅਤ ਕਰੋ। ਸਹੀ ਸ਼ਰਤਾਂ ਜਾਇਦਾਦ ਅਤੇ ਮੌਰਗੇਜ ਮਨਜ਼ੂਰੀ ਦੀ ਪੁਸ਼ਟੀ ਕਰਨ ਲਈ ਸਮਾਂ ਦਿੰਦੀਆਂ ਹਨ।",
    "gl_step4_h3": "ਲਾਈਵ ਡੀਲ ਜਮ੍ਹਾਂ ਕਰੋ",
    "gl_step4_p": "ਰਿਣਦਾਤਾ ਕਰਜ਼ਾ ਲੈਣ ਵਾਲੇ, ਜਾਇਦਾਦ, ਡਾਊਨ ਪੇਮੈਂਟ, ਲੋੜ ਪੈਣ 'ਤੇ ਮੁਲਾਂਕਣ, ਅਤੇ ਖਰੀਦ ਇਕਰਾਰਨਾਮੇ ਦੀ ਸਮੀਖਿਆ ਕਰਦਾ ਹੈ। ਉਹ ਸ਼ਰਤਾਂ ਨਾਲ ਇੱਕ ਵਚਨਬੱਧਤਾ ਜਾਰੀ ਕਰ ਸਕਦੇ ਹਨ ਜੋ ਕਲੋਜ਼ਿੰਗ ਤੋਂ ਪਹਿਲਾਂ ਪੂਰੀਆਂ ਹੋਣੀਆਂ ਚਾਹੀਦੀਆਂ ਹਨ।",
    "gl_step5_h3": "ਆਪਣੇ ਵਕੀਲ ਨਾਲ ਬੰਦ ਕਰੋ",
    "gl_step5_p": "ਤੁਹਾਡਾ ਵਕੀਲ ਜਾਂ ਨੋਟਰੀ ਮੌਰਗੇਜ ਰਜਿਸਟਰ ਕਰਦਾ ਹੈ, ਟਾਈਟਲ ਸੰਭਾਲਦਾ ਹੈ, ਰਿਣਦਾਤਾ ਫੰਡ ਪ੍ਰਾਪਤ ਕਰਦਾ ਹੈ, ਤੁਹਾਡੀ ਬਾਕੀ ਡਾਊਨ ਪੇਮੈਂਟ ਅਤੇ ਕਲੋਜ਼ਿੰਗ ਲਾਗਤਾਂ ਇਕੱਠੀਆਂ ਕਰਦਾ ਹੈ, ਅਤੇ ਜਾਇਦਾਦ ਟ੍ਰਾਂਸਫਰ ਪੂਰਾ ਕਰਦਾ ਹੈ।",
    "gl_qual_kicker": "ਯੋਗਤਾ",
    "gl_qual_h2": "ਰਿਣਦਾਤੇ ਕਿਵੇਂ ਫੈਸਲਾ ਕਰਦੇ ਹਨ ਕਿ ਤੁਸੀਂ ਕਿੰਨਾ ਉਧਾਰ ਲੈ ਸਕਦੇ ਹੋ",
    "gl_qual_p": "ਮੌਰਗੇਜ ਯੋਗਤਾ ਇੱਕ ਜੋਖਮ ਸਮੀਖਿਆ ਹੈ। ਰਿਣਦਾਤੇ ਵੇਖਦੇ ਹਨ ਕਿ ਕੀ ਤੁਸੀਂ ਮੌਰਗੇਜ ਭੁਗਤਾਨ ਕਰ ਸਕਦੇ ਹੋ, ਕੀ ਜਾਇਦਾਦ ਸਵੀਕਾਰਯੋਗ ਸੁਰੱਖਿਆ ਹੈ, ਅਤੇ ਕੀ ਪੂਰੀ ਕਹਾਣੀ ਸਮਝਦਾਰੀ ਰੱਖਦੀ ਹੈ।",
    "gl_qual_h3": "ਰਿਣਦਾਤਾ ਪੰਜ ਮੁੱਖ ਖੇਤਰਾਂ ਨੂੰ ਵੇਖਦਾ ਹੈ",
