    "gl_gds_dt": "GDS",
    "gl_gds_dd": "ਕੁੱਲ ਕਰਜ਼ਾ ਸੇਵਾ ਰਿਹਾਇਸ਼ੀ ਖਰਚਿਆਂ ਦੀ ਕੁੱਲ ਆਮਦਨ ਨਾਲ ਤੁਲਨਾ ਕਰਦੀ ਹੈ। ਰਿਹਾਇਸ਼ੀ ਖਰਚਿਆਂ ਵਿੱਚ ਆਮ ਤੌਰ 'ਤੇ ਮੌਰਗੇਜ ਭੁਗਤਾਨ, ਜਾਇਦਾਦ ਟੈਕਸ, ਹੀਟਿੰਗ, ਅਤੇ ਲਾਗੂ ਹੋਣ 'ਤੇ 50% ਕੰਡੋ ਫੀਸਾਂ ਸ਼ਾਮਲ ਹੁੰਦੀਆਂ ਹਨ।",
