    "gl_dp_p": "ਤੁਹਾਡੀ ਡਾਊਨ ਪੇਮੈਂਟ ਮੌਰਗੇਜ ਰਕਮ, ਬੀਮਾ ਲੋੜ, ਰਿਣਦਾਤਾ ਵਿਕਲਪਾਂ, ਅਤੇ ਲੋੜੀਂਦੀ ਕਲੋਜ਼ਿੰਗ ਨਕਦੀ ਨੂੰ ਪ੍ਰਭਾਵਿਤ ਕਰਦੀ ਹੈ। ਕੈਨੇਡਾ ਵਿੱਚ, ਘੱਟੋ-ਘੱਟ ਡਾਊਨ ਪੇਮੈਂਟ ਖਰੀਦ ਮੁੱਲ 'ਤੇ ਨਿਰਭਰ ਕਰਦੀ ਹੈ।",
