    "gl_dpsrc_li5": "ਉਧਾਰ ਲਏ ਫੰਡ ਸਿਰਫ਼ ਤਾਂ ਹੀ ਜੇ ਰਿਣਦਾਤਾ ਇਸਦੀ ਇਜਾਜ਼ਤ ਦਿੰਦਾ ਹੈ ਅਤੇ ਭੁਗਤਾਨ ਨੂੰ ਯੋਗਤਾ ਵਿੱਚ ਸ਼ਾਮਲ ਕਰਦਾ ਹੈ।",
    "gl_mli_h3": "ਮੌਰਗੇਜ ਲੋਨ ਬੀਮਾ",
    "gl_mli_p": "ਜਦੋਂ ਡਾਊਨ ਪੇਮੈਂਟ 20% ਤੋਂ ਘੱਟ ਹੁੰਦੀ ਹੈ ਤਾਂ ਆਮ ਤੌਰ 'ਤੇ ਮੌਰਗੇਜ ਲੋਨ ਬੀਮਾ ਲੋੜੀਂਦਾ ਹੈ। ਇਹ ਰਿਣਦਾਤੇ ਨੂੰ ਸੁਰੱਖਿਅਤ ਕਰਦਾ ਹੈ ਜੇ ਕਰਜ਼ਾ ਲੈਣ ਵਾਲਾ ਡਿਫਾਲਟ ਕਰਦਾ ਹੈ, ਪਰ ਇਹ ਖਰੀਦਦਾਰਾਂ ਨੂੰ ਛੋਟੀ ਡਾਊਨ ਪੇਮੈਂਟ ਨਾਲ ਯੋਗ ਹੋਣ ਵਿੱਚ ਮਦਦ ਕਰ ਸਕਦਾ ਹੈ। ਪ੍ਰੀਮੀਅਮ ਆਮ ਤੌਰ 'ਤੇ ਮੌਰਗੇਜ ਰਕਮ ਵਿੱਚ ਜੋੜਿਆ ਜਾਂਦਾ ਹੈ, ਜੋ ਲੋਨ ਅਤੇ ਭੁਗਤਾਨ ਨੂੰ ਵਧਾਉਂਦਾ ਹੈ।",
    "gl_prod_kicker": "ਮੌਰਗੇਜ ਕਿਸਮਾਂ",
    "gl_prod_h2": "ਸਹੀ ਮੌਰਗੇਜ ਢਾਂਚਾ ਚੁਣਨਾ",
