    "gl_rr_renewal_p": "ਨਵਿਆਉਣ ਉਦੋਂ ਹੁੰਦਾ ਹੈ ਜਦੋਂ ਤੁਹਾਡੀ ਮੌਰਗੇਜ ਮਿਆਦ ਖਤਮ ਹੁੰਦੀ ਹੈ। ਤੁਸੀਂ ਆਪਣੇ ਮੌਜੂਦਾ ਰਿਣਦਾਤੇ ਦੀ ਪੇਸ਼ਕਸ਼ ਸਵੀਕਾਰ ਕਰ ਸਕਦੇ ਹੋ, ਗੱਲਬਾਤ ਕਰ ਸਕਦੇ ਹੋ, ਰਿਣਦਾਤਾ ਬਦਲ ਸਕਦੇ ਹੋ, ਮਿਆਦ ਬਦਲ ਸਕਦੇ ਹੋ, ਭੁਗਤਾਨ ਬਾਰੰਬਾਰਤਾ ਬਦਲ ਸਕਦੇ ਹੋ, ਜਾਂ ਰਣਨੀਤੀ ਵਿਵਸਥਿਤ ਕਰ ਸਕਦੇ ਹੋ। ਪਹਿਲੇ ਨਵਿਆਉਣ ਪੱਤਰ ਨੂੰ ਅੰਤਿਮ ਜਵਾਬ ਨਾ ਸਮਝੋ।",
    "gl_rr_li1": "ਮਿਆਦ ਪੂਰੀ ਹੋਣ ਤੋਂ ਕੁਝ ਮਹੀਨੇ ਪਹਿਲਾਂ ਵਿਕਲਪਾਂ ਦੀ ਸਮੀਖਿਆ ਕਰਨੀ ਸ਼ੁਰੂ ਕਰੋ।",
    "gl_rr_li2": "ਦਰ, ਭੁਗਤਾਨ, ਪ੍ਰੀਪੇਮੈਂਟ ਵਿਸ਼ੇਸ਼ ਅਧਿਕਾਰ, ਜੁਰਮਾਨੇ, ਪੋਰਟੇਬਿਲਟੀ, ਅਤੇ ਸੇਵਾ ਦੀ ਤੁਲਨਾ ਕਰੋ।",
    "gl_rr_li3": "ਪੁੱਛੋ ਕਿ ਕੀ ਰਿਣਦਾਤਾ ਬਦਲਣ ਨਾਲ ਸੈੱਟਅੱਪ, ਡਿਸਚਾਰਜ, ਮੁਲਾਂਕਣ, ਕਾਨੂੰਨੀ, ਜਾਂ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਲਾਗਤਾਂ ਬਣਦੀਆਂ ਹਨ।",
    "gl_rr_li4": "ਜੇ ਤੁਹਾਡੇ ਕੋਲ ਪਹਿਲਾਂ ਹੀ ਮੌਰਗੇਜ ਲੋਨ ਬੀਮਾ ਹੈ, ਤਾਂ ਬਦਲਣ ਤੋਂ ਪਹਿਲਾਂ ਬੀਮਾ ਸਰਟੀਫਿਕੇਟ ਵੇਰਵੇ ਮੰਗੋ।",
    "gl_rr_refi_h3": "ਰੀਫਾਈਨੈਂਸ",
    "gl_rr_refi_p": "ਰੀਫਾਈਨੈਂਸ ਦਾ ਮਤਲਬ ਹੈ ਮਿਆਦ ਪੂਰੀ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਜਾਂ ਉਸ ਸਮੇਂ ਮੌਰਗੇਜ ਨੂੰ ਬਦਲਣਾ, ਆਮ ਤੌਰ 'ਤੇ ਇਕੁਇਟੀ ਤੱਕ ਪਹੁੰਚ ਕਰਨ, ਕਰਜ਼ਾ ਇਕਸਾਰ ਕਰਨ, ਅਮੌਰਟਾਈਜ਼ੇਸ਼ਨ ਬਦਲਣ, ਕਰਜ਼ਾ ਲੈਣ ਵਾਲੇ ਨੂੰ ਹਟਾਉਣ/ਜੋੜਨ, ਜਾਂ ਢਾਂਚਾ ਸੁਧਾਰਨ ਲਈ। ਇੱਕ ਰੀਫਾਈਨੈਂਸ ਨੂੰ ਆਮ ਤੌਰ 'ਤੇ ਯੋਗਤਾ ਦੀ ਲੋੜ ਹੁੰਦੀ ਹੈ ਅਤੇ ਜੇ ਮਿਆਦ ਖਤਮ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਕੀਤਾ ਜਾਂਦਾ ਹੈ ਤਾਂ ਇਸ ਵਿੱਚ ਮੁਲਾਂਕਣ, ਕਾਨੂੰਨੀ ਕੰਮ, ਅਤੇ ਜੁਰਮਾਨੇ ਸ਼ਾਮਲ ਹੋ ਸਕਦੇ ਹਨ।",
    "gl_rr_penalty_h3": "ਪ੍ਰੀਪੇਮੈਂਟ ਜੁਰਮਾਨੇ",
    "gl_rr_penalty_p": "ਇੱਕ ਰਿਣਦਾਤਾ ਜੁਰਮਾਨਾ ਲਗਾ ਸਕਦਾ ਹੈ ਜੇ ਤੁਸੀਂ ਇੱਕ ਕਲੋਜ਼ਡ ਮੌਰਗੇਜ ਤੋੜਦੇ ਹੋ, ਇਜਾਜ਼ਤ ਤੋਂ ਵੱਧ ਭੁਗਤਾਨ ਕਰਦੇ ਹੋ, ਮਿਆਦ ਖਤਮ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਮੌਰਗੇਜ ਟ੍ਰਾਂਸਫਰ ਕਰਦੇ ਹੋ, ਜਾਂ ਪੂਰਾ ਬਕਾਇਆ ਜਲਦੀ ਭੁਗਤਾਨ ਕਰਦੇ ਹੋ। ਓਪਨ ਮੌਰਗੇਜ ਆਮ ਤੌਰ 'ਤੇ ਬਿਨਾਂ ਜੁਰਮਾਨੇ ਭੁਗਤਾਨ ਦੀ ਆਗਿਆ ਦਿੰਦੇ ਹਨ ਪਰ ਅਕਸਰ ਵੱਧ ਦਰਾਂ ਰੱਖਦੇ ਹਨ।",
