    "gl_tree_refi_d": "ਰਕਮ, ਅਮੌਰਟਾਈਜ਼ੇਸ਼ਨ, ਮਾਲਕੀ, ਜਾਂ ਕਰਜ਼ਾ ਯੋਜਨਾ ਬਦਲੋ",
    "gl_broker_kicker": "ਬ੍ਰੋਕਰ ਨਾਲ ਕੰਮ ਕਰਨਾ",
    "gl_broker_h2": "ਇੱਕ ਲਾਇਸੰਸਸ਼ੁਦਾ ਮੌਰਗੇਜ ਪੇਸ਼ੇਵਰ ਨੂੰ ਤੁਹਾਨੂੰ ਕੀ ਸਮਝਣ ਵਿੱਚ ਮਦਦ ਕਰਨੀ ਚਾਹੀਦੀ ਹੈ",
    "gl_broker_p": "ਓਨਟਾਰੀਓ ਵਿੱਚ, ਮੌਰਗੇਜ ਬ੍ਰੋਕਰੇਜ, ਬ੍ਰੋਕਰ, ਏਜੰਟ, ਅਤੇ ਪ੍ਰਸ਼ਾਸਕ FSRA ਦੁਆਰਾ ਨਿਯੰਤ੍ਰਿਤ ਹਨ ਜਦੋਂ ਤੱਕ ਛੋਟ ਨਾ ਹੋਵੇ। ਇੱਕ ਲਾਇਸੰਸਸ਼ੁਦਾ ਮੌਰਗੇਜ ਪੇਸ਼ੇਵਰ ਰਿਣਦਾਤਾ ਵਿਕਲਪਾਂ ਦੀ ਤੁਲਨਾ ਕਰ ਸਕਦਾ ਹੈ, ਦਸਤਾਵੇਜ਼ ਇਕੱਠੇ ਕਰ ਸਕਦਾ ਹੈ, ਸ਼ਰਤਾਂ ਅਤੇ ਜੋਖਮ ਸਮਝਾ ਸਕਦਾ ਹੈ, ਅਤੇ ਮਨਜ਼ੂਰੀ ਅਤੇ ਕਲੋਜ਼ਿੰਗ ਰਾਹੀਂ ਫਾਈਲ ਦੀ ਅਗਵਾਈ ਕਰ ਸਕਦਾ ਹੈ।",
