    "gl_q1": "ਕੀ ਤੁਸੀਂ FSRA ਨਾਲ ਲਾਇਸੰਸਸ਼ੁਦਾ ਹੋ, ਅਤੇ ਤੁਹਾਡਾ ਲਾਇਸੈਂਸ ਪੱਧਰ ਕੀ ਹੈ?",
