    "gl_q4": "ਕਿਹੜੇ ਰਿਣਦਾਤਿਆਂ 'ਤੇ ਵਿਚਾਰ ਕੀਤਾ ਜਾ ਰਿਹਾ ਹੈ, ਅਤੇ ਕਿਉਂ?",
    "gl_q5": "ਜੋਖਮ, ਜੁਰਮਾਨੇ, ਪਾਬੰਦੀਆਂ, ਅਤੇ ਉਧਾਰ ਲੈਣ ਦੀ ਕੁੱਲ ਲਾਗਤ ਕੀ ਹੈ?",
