    "gt_apr_dd": "ਸਾਲਾਨਾ ਪ੍ਰਤੀਸ਼ਤ ਦਰ। ਇੱਕ ਵਿਆਪਕ ਸਾਲਾਨਾ ਲਾਗਤ ਮਾਪ ਜਿਸ ਵਿੱਚ ਵਿਆਜ ਅਤੇ ਕੁਝ ਉਧਾਰ ਲਾਗਤਾਂ ਸ਼ਾਮਲ ਹੋ ਸਕਦੀਆਂ ਹਨ।",
