    "cr_gallery_cap1": "ਗੰਭੀਰ ਵਿਕਰੀ ਅਤੇ ਮਾਰਕੀਟ ਗੱਲਬਾਤ ਲਈ ਪੇਸ਼ੇਵਰ ਕਮਰੇ।",
    "cr_gallery_cap2": "ਏਜੰਟਾਂ, ਰਿਣਦਾਤਿਆਂ, ਅਤੇ ਵਿਕਾਸ-ਮੁਖੀ ਪੇਸ਼ੇਵਰਾਂ ਨਾਲ ਲਾਈਵ ਮੌਰਗੇਜ ਸਿਖਲਾਈ।",
