    "cr_dd_style": "ਰਿਸ਼ਤਾ-ਸੰਚਾਲਿਤ, ਗਾਹਕ-ਸਾਹਮਣੇ, ਪ੍ਰਦਰਸ਼ਨ-ਕੇਂਦਰਿਤ",
    "cr_look_h3": "ਅਸੀਂ ਕੀ ਭਾਲਦੇ ਹਾਂ",
    "cr_look_li1": "ਮੌਰਗੇਜ ਏਜੰਟ ਲਾਇਸੈਂਸ ਜਾਂ ਲਾਇਸੈਂਸਿੰਗ ਵੱਲ ਸਰਗਰਮ ਰਸਤਾ।",
