    "cr_wo_li3": "ਕੈਨੇਡਾ ਵਿੱਚ ਨਵੇਂ, ਸਵੈ-ਰੁਜ਼ਗਾਰ, ਅਤੇ ਵਿਕਲਪਕ ਲੋਨ ਦ੍ਰਿਸ਼।",
    "cr_wo_li4": "ਤਜਰਬਾ ਵਧਣ ਦੇ ਨਾਲ ਕਮਰਸ਼ੀਅਲ ਅਤੇ ਉਸਾਰੀ ਮੌਕੇ।",
    "cr_std_kicker": "RDC ਮਿਆਰ",
    "cr_std_h2": "ਸੁਤੰਤਰ ਕੰਮ, ਪੇਸ਼ੇਵਰ ਉਮੀਦਾਂ।",
    "cr_std_p": "ਕਮਿਸ਼ਨ-ਆਧਾਰਿਤ ਮੌਰਗੇਜ ਕੰਮ ਪਹਿਲ ਦਾ ਇਨਾਮ ਦਿੰਦਾ ਹੈ। ਅਸੀਂ ਉਹਨਾਂ ਲੋਕਾਂ ਦੀ ਭਾਲ ਕਰਦੇ ਹਾਂ ਜੋ ਪਾਲਣਾ ਕਰਦੇ ਹਨ, ਗਾਹਕ ਭਰੋਸੇ ਦੀ ਰੱਖਿਆ ਕਰਦੇ ਹਨ, ਅਤੇ ਧਿਆਨ ਨਾਲ ਫਾਈਲਾਂ ਨੂੰ ਅੱਗੇ ਵਧਾਉਂਦੇ ਹਨ।",
    "cr_s1_h3": "ਫਾਲੋ-ਅੱਪ ਦੀ ਜ਼ਿੰਮੇਵਾਰੀ ਲਓ",
    "cr_s1_p": "ਗਾਹਕਾਂ ਅਤੇ ਰੈਫਰਲ ਭਾਈਵਾਲਾਂ ਨੂੰ ਹਮੇਸ਼ਾ ਪਤਾ ਹੋਣਾ ਚਾਹੀਦਾ ਹੈ ਕਿ ਅੱਗੇ ਕੀ ਹੋ ਰਿਹਾ ਹੈ, ਕੀ ਗੁੰਮ ਹੈ, ਅਤੇ ਉਹਨਾਂ ਨੂੰ ਤੁਹਾਡੇ ਤੋਂ ਕਦੋਂ ਸੁਣਨ ਨੂੰ ਮਿਲੇਗਾ।",
    "cr_s2_h3": "ਫਾਈਲ ਦਾ ਸਤਿਕਾਰ ਕਰੋ",
    "cr_s2_p": "ਮੌਰਗੇਜ ਸਲਾਹ ਨਿੱਜੀ ਵਿੱਤੀ ਵੇਰਵਿਆਂ 'ਤੇ ਨਿਰਭਰ ਕਰਦੀ ਹੈ। ਅਸੀਂ ਦਸਤਾਵੇਜ਼ਾਂ, ਨੋਟਸ, ਰਿਣਦਾਤਾ ਸ਼ਰਤਾਂ, ਅਤੇ ਗਾਹਕ ਗੱਲਬਾਤ ਦੀ ਧਿਆਨ ਨਾਲ ਸੰਭਾਲ ਦੀ ਉਮੀਦ ਕਰਦੇ ਹਾਂ।",
    "cr_s3_h3": "ਆਪਣੀ ਮਾਰਕੀਟ ਬਣਾਓ",
    "cr_s3_p": "ਸਭ ਤੋਂ ਮਜ਼ਬੂਤ ਏਜੰਟ ਨੈੱਟਵਰਕਿੰਗ, ਰੈਫਰਲ, ਸਥਾਨਕ ਮੌਜੂਦਗੀ, ਅਤੇ ਲਗਾਤਾਰ ਗਾਹਕ ਸਿੱਖਿਆ ਰਾਹੀਂ ਮੌਕਾ ਬਣਾਉਂਦੇ ਹਨ।",
    "cr_faq_kicker": "ਕਰੀਅਰ ਸਵਾਲ",
    "cr_faq_h2": "ਅਪਲਾਈ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ।",
    "cr_faq_p": "ਇਹ ਫੈਸਲਾ ਕਰਨ ਲਈ ਇਸ ਤੇਜ਼ ਸੰਖੇਪ ਜਾਣਕਾਰੀ ਦੀ ਵਰਤੋਂ ਕਰੋ ਕਿ ਕੀ ਮੌਕਾ ਤੁਹਾਡੇ ਕੰਮ ਕਰਨ ਦੇ ਤਰੀਕੇ ਨਾਲ ਮੇਲ ਖਾਂਦਾ ਹੈ।",
    "cr_faq1_q": "ਕੀ ਇਹ ਤਨਖਾਹ ਵਾਲੀ ਭੂਮਿਕਾ ਹੈ?",
    "cr_faq1_a": "ਨਹੀਂ। ਇਹ ਉਹਨਾਂ ਲੋਕਾਂ ਲਈ ਇੱਕ ਕਮਿਸ਼ਨ-ਆਧਾਰਿਤ ਮੌਕਾ ਹੈ ਜੋ ਵਪਾਰ ਵਿਕਸਤ ਕਰਨ ਅਤੇ ਫੰਡ ਕੀਤੀਆਂ ਮੌਰਗੇਜ ਫਾਈਲਾਂ ਰਾਹੀਂ ਕਮਾਈ ਕਰਨ ਨਾਲ ਸਹਿਜ ਹਨ।",
    "cr_faq2_q": "ਕੀ ਮੈਨੂੰ ਪਹਿਲਾਂ ਤੋਂ ਲਾਇਸੰਸਸ਼ੁਦਾ ਹੋਣ ਦੀ ਲੋੜ ਹੈ?",
    "cr_faq2_a": "ਲਾਇਸੰਸਸ਼ੁਦਾ ਏਜੰਟ ਅਤੇ ਬ੍ਰੋਕਰ ਅਪਲਾਈ ਕਰਨ ਲਈ ਉਤਸ਼ਾਹਿਤ ਹਨ। ਜੇ ਤੁਸੀਂ ਸਰਗਰਮੀ ਨਾਲ ਲਾਇਸੈਂਸਿੰਗ ਪੂਰੀ ਕਰ ਰਹੇ ਹੋ, ਤੁਸੀਂ ਫਿਰ ਵੀ ਆਪਣੀ ਜਾਣ-ਪਛਾਣ ਦੇ ਸਕਦੇ ਹੋ ਅਤੇ ਆਪਣੀ ਸਮਾਂ-ਸੀਮਾ ਸਾਂਝੀ ਕਰ ਸਕਦੇ ਹੋ।",
