    "cr_faq3_a": "ਆਪਣੀ ਲਾਇਸੈਂਸਿੰਗ ਸਥਿਤੀ, ਮੌਰਗੇਜ ਜਾਂ ਵਿਕਰੀ ਤਜਰਬਾ, ਟੀਚਾ ਮਾਰਕੀਟ, ਅਤੇ ਤੁਸੀਂ Royal Den Capital ਨਾਲ ਆਪਣਾ ਕਰੀਅਰ ਕਿਉਂ ਬਣਾਉਣਾ ਚਾਹੁੰਦੇ ਹੋ, ਸਾਂਝਾ ਕਰੋ।",
